const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // Geometry: Mount Fuji peak buffered to cover the mountain area
    const fuji = ee.Geometry.Point([138.7274, 35.3606]);
    const roi = fuji.buffer(15000);

    // Helpers
    function maskLandsatSR(img) {
      const qa = img.select('QA_PIXEL');
      // Keep pixels that are not dilated cloud, cirrus, cloud, or cloud shadow. Do NOT mask snow.
      const mask = qa.bitwiseAnd(1 << 1).eq(0) // dilated cloud
        .and(qa.bitwiseAnd(1 << 2).eq(0))      // cirrus
        .and(qa.bitwiseAnd(1 << 3).eq(0))      // cloud
        .and(qa.bitwiseAnd(1 << 4).eq(0));     // cloud shadow
      return img.updateMask(mask);
    }

    function ndsiCollection(collectionId, green, swir1, start, end, geom) {
      return ee.ImageCollection(collectionId)
        .filterDate(start, end)
        .filterBounds(geom)
        .map(maskLandsatSR)
        .map(function(img) {
          const g = img.select(green).multiply(0.0000275).add(-0.2);
          const s1 = img.select(swir1).multiply(0.0000275).add(-0.2);
          const sum = g.add(s1);
          const ndsi = g.subtract(s1).divide(sum).updateMask(sum.neq(0)).rename('NDSI');
          return ndsi.copyProperties(img, ['system:time_start']);
        });
    }

    function buildAllLandsat(start, end, geom) {
      const l5 = ndsiCollection('LANDSAT/LT05/C02/T1_L2', 'SR_B2', 'SR_B5', start, end, geom);
      const l7 = ndsiCollection('LANDSAT/LE07/C02/T1_L2', 'SR_B2', 'SR_B5', start, end, geom);
      const l8 = ndsiCollection('LANDSAT/LC08/C02/T1_L2', 'SR_B3', 'SR_B6', start, end, geom);
      const l9 = ndsiCollection('LANDSAT/LC09/C02/T1_L2', 'SR_B3', 'SR_B6', start, end, geom);
      return l5.merge(l7).merge(l8).merge(l9);
    }

    async function getNumber(x) {
      return await new Promise((resolve, reject) => x.getInfo(resolve, reject));
    }
    async function getDict(x) {
      return await new Promise((resolve, reject) => x.getInfo(resolve, reject));
    }

    async function analyzeDecember(year) {
      const start = ee.Date.fromYMD(year, 12, 1);
      const end = ee.Date.fromYMD(year + 1, 1, 1);
      let col = buildAllLandsat(start, end, roi);
      let count = await getNumber(col.size());
      // Fallback: widen window if empty
      if (count === 0) {
        const fbStart = ee.Date.fromYMD(year, 11, 20);
        const fbEnd = ee.Date.fromYMD(year + 1, 1, 10);
        col = buildAllLandsat(fbStart, fbEnd, roi);
        count = await getNumber(col.size());
      }
      if (count === 0) {
        return { year, images: 0, validPix: 0, totalPix: 0, mean: null };
      }
      const comp = col.median().clip(roi).select('NDSI');
      const validObj = await getDict(comp.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: roi,
        scale: 1000,
        maxPixels: 1e9
      }));
      const validPix = validObj ? (validObj.NDSI || 0) : 0;
      const totalObj = await getDict(ee.Image.constant(1).rename('one').reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: roi,
        scale: 1000,
        maxPixels: 1e9
      }));
      const totalPix = totalObj ? (totalObj.one || 0) : 0;
      if (validPix === 0) {
        return { year, images: count, validPix: 0, totalPix: totalPix, mean: null };
      }
      const meanObj = await getDict(comp.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: roi,
        scale: 1000,
        maxPixels: 1e9
      }));
      const mean = meanObj ? meanObj.NDSI : null;
      return { year, images: count, validPix, totalPix, mean };
    }

    // Analyze 2020
    const dec2020 = await analyzeDecember(2020);
    if (dec2020.images === 0) {
      console.log('2020-12 Images: 0');
      console.log('C1');
      return;
    }
    if (dec2020.validPix === 0) {
      const keep = dec2020.totalPix > 0 ? (100.0 * 0 / dec2020.totalPix) : 0;
      console.log(`2020-12 Images: ${dec2020.images}, ValidPix: 0, Clear%: ${keep.toFixed(1)}%, MeanNDSI: null`);
      console.log('C2');
      return;
    }
    if (dec2020.mean === null || isNaN(dec2020.mean) || Math.abs(dec2020.mean) > 1) {
      console.log(`2020-12 Images: ${dec2020.images}, ValidPix: ${dec2020.validPix}, Clear%: ${(100.0 * dec2020.validPix / dec2020.totalPix).toFixed(1)}%, MeanNDSI: ${dec2020.mean}`);
      console.log('C3');
      return;
    }
    console.log(`2020-12 Images: ${dec2020.images}, ValidPix: ${dec2020.validPix}, Clear%: ${(100.0 * dec2020.validPix / dec2020.totalPix).toFixed(1)}%, MeanNDSI: ${dec2020.mean.toFixed(3)}`);

    // Analyze 2005..2015
    let prevStats = [];
    for (let y = 2005; y <= 2015; y++) {
      const st = await analyzeDecember(y);
      if (st.images === 0) {
        console.log(`${y}-12 Images: 0`);
      } else if (st.validPix === 0) {
        const keep = st.totalPix > 0 ? (100.0 * 0 / st.totalPix) : 0;
        console.log(`${y}-12 Images: ${st.images}, ValidPix: 0, Clear%: ${keep.toFixed(1)}%, MeanNDSI: null`);
      } else if (st.mean === null || isNaN(st.mean) || Math.abs(st.mean) > 1) {
        console.log(`${y}-12 Images: ${st.images}, ValidPix: ${st.validPix}, Clear%: ${(100.0 * st.validPix / st.totalPix).toFixed(1)}%, MeanNDSI: ${st.mean}`);
      } else {
        console.log(`${y}-12 Images: ${st.images}, ValidPix: ${st.validPix}, Clear%: ${(100.0 * st.validPix / st.totalPix).toFixed(1)}%, MeanNDSI: ${st.mean.toFixed(3)}`);
        prevStats.push(st);
      }
    }

    const haveAnyPrevImages = await (async () => {
      let any = false;
      for (let y = 2005; y <= 2015; y++) {
        const st = await analyzeDecember(y); // This would duplicate work; better to use prevStats
        // But to avoid extra calls, infer from prevStats and prints: if prevStats length > 0 then we had images+valid
        any = true;
        break;
      }
      return any;
    })();

    if (prevStats.length === 0) {
      // If none of the previous years produced a valid mean despite attempts
      // Distinguish between C1 (no images at all) and C2 (images but no valid pixels)
      // Use the printed lines; Here if at least one line had "Images: 0" for all, it's C1; else C2.
      // To decide programmatically, re-run quick check for images existence across years:
      let anyPrevImages = false;
      for (let y = 2005; y <= 2015; y++) {
        // Build minimal check collection
        const start = ee.Date.fromYMD(y, 12, 1);
        const end = ee.Date.fromYMD(y + 1, 1, 1);
        const col = buildAllLandsat(start, end, roi);
        const size = await getNumber(col.size());
        if (size > 0) {
          anyPrevImages = true;
          break;
        }
      }
      if (!anyPrevImages) {
        console.log('C1');
        return;
      } else {
        console.log('C2');
        return;
      }
    }

    // Compute min mean among previous valid years
    let minPrev = null;
    let minYear = null;
    prevStats.forEach(s => {
      if (s.mean !== null && !isNaN(s.mean) && Math.abs(s.mean) <= 1) {
        if (minPrev === null || s.mean < minPrev) {
          minPrev = s.mean;
          minYear = s.year;
        }
      }
    });

    if (minPrev === null || isNaN(minPrev) || Math.abs(minPrev) > 1) {
      console.log('C3');
      return;
    }

    console.log(`Min 2005-2015 MeanNDSI: ${minPrev.toFixed(3)} (Year: ${minYear})`);

    // Final comparison
    const answer = dec2020.mean < minPrev ? 'A' : 'B';
    console.log(answer);
  } catch (err) {
    // In case of any API, naming, or memory error
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
